 62	pub fn compile_src(src: &str, file: &str, opts: &Options) -> Result<(String, Vec<diag::Diag>), (diag::Diag, Vec<diag::Diag>)> {
 63	    let (doc, _comments) = parser::parse(src).map_err(|e| (e, vec![]))?;
