 65	    let root = compile::root_decls_node(&sheet);
 66	    let mut b = scene::Builder::new(&sheet, src);
 67	    b.add(root, None);
 68	    b.build_stmts(&doc.stmts, 0).map_err(|e| (e, vec![]))?;
 69	    icon::validate(&b.nodes, b.sheet, file, opts).map_err(|e| (e, vec![]))?;
 70	    b.resolve_links().map_err(|e| (e, vec![]))?;
 71	    page::root_fixup(&mut b.nodes, b.sheet);
 72	    b.unworn_class_warnings();
 73	    let nodes = std::mem::take(&mut b.nodes);
 74	    let links = std::mem::take(&mut b.links);
 75	    let mut warnings = std::mem::take(&mut b.warnings);
 76	    drop(b);
 77	    let mut ctx = compile::Ctx {
 78	        src: src.to_string(),
 79	        file: file.to_string(),
 80	        sheet,
 81	        nodes,
 82	        comp: vec![],
 83	        links,
 84	        warnings: std::mem::take(&mut warnings),
