 56	fn jaro(a: &str, b: &str) -> f64 {
 57	    let a: Vec<char> = a.chars().collect();
 58	    let b: Vec<char> = b.chars().collect();
 59	    if a.is_empty() && b.is_empty() {
 60	        return 1.0;
 61	    }
 62	    if a.is_empty() || b.is_empty() {
 63	        return 0.0;
 64	    }
 65	    let range = (a.len().max(b.len()) / 2).saturating_sub(1);
 66	    let mut am = vec![false; a.len()];
 67	    let mut bm = vec![false; b.len()];
 68	    let mut m = 0usize;
 69	    for i in 0..a.len() {
 70	        let lo = i.saturating_sub(range);
 71	        let hi = (i + range + 1).min(b.len());
 72	        for j in lo..hi {
 73	            if !bm[j] && a[i] == b[j] {
 74	                am[i] = true;
 75	                bm[j] = true;
 76	                m += 1;
 77	                break;
 78	            }
 79	        }
 80	    }
 81	    if m == 0 {
 82	        return 0.0;
 83	    }
 84	    let mut t = 0usize;
 85	    let mut k = 0usize;
 86	    for i in 0..a.len() {
 87	        if am[i] {
 88	            while !bm[k] {
 89	                k += 1;
 90	            }
 91	            if a[i] != b[k] {
 92	                t += 1;
 93	            }
 94	            k += 1;
 95	        }
 96	    }
 97	    let m = m as f64;
 98	    (m / a.len() as f64 + m / b.len() as f64 + (m - t as f64 / 2.0) / m) / 3.0
 99	}
