101	fn suggest(given: &str, cands: &[&str]) -> Option<String> {
102	    let mut best: Option<(f64, &str)> = None;
103	    for c in cands {
104	        let s = jaro(given, c);
105	        if s > 0.7 && best.map(|b| s > b.0).unwrap_or(true) {
106	            best = Some((s, c));
107	        }
108	    }
109	    best.map(|b| b.1.to_string())
110	}
