124	pub fn parse(args: &[String]) -> Outcome {
125	    let bin = std::path::Path::new(&args[0]).file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_else(|| "lini".into());
126	    let mut opts = crate::Options { format: "svg".into(), ..Default::default() };
127	    let mut input: Option<String> = None;
128	    let mut seen: Vec<&'static str> = Vec::new(); // long names in order seen
129	    let mut i = 1;
130	    let mut only_pos = false;
131	    let mut want_help = false;
132	    let mut want_version = false;
133	    let used_usage = |seen: &Vec<&'static str>, extra: Option<&str>| -> String {
134	        let mut parts = vec![bin.clone()];
135	        for d in MAIN_OPTS {
136	            if seen.contains(&d.long) || extra == Some(d.long) {
137	                match d.value {
138	                    Some(v) => parts.push(format!("--{} <{}>", d.long, v)),
139	                    None => parts.push(format!("--{}", d.long)),
140	                }
141	            }
142	        }
143	        parts.push("<INPUT>".into());
144	        format!("Usage: {}\n", parts.join(" "))
145	    };
146	    while i < args.len() {
147	        let a = args[i].clone();
148	        i += 1;
149	        if !only_pos && a == "--" {
150	            only_pos = true;
151	            continue;
152	        }
153	        if !only_pos && a.starts_with("--") {
154	            let body = &a[2..];
155	            let (name, inline_val) = match body.find('=') {
156	                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
157	                None => (body, None),
158	            };
159	            let def = match MAIN_OPTS.iter().find(|d| d.long == name) {
160	                Some(d) => d,
161	                None => {
162	                    let names: Vec<&str> = MAIN_OPTS.iter().map(|d| d.long).collect();
163	                    if let Some(s) = suggest(name, &names) {
164	                        let sname = MAIN_OPTS.iter().find(|d| d.long == s).unwrap().long;
165	                        return Outcome::Fail(format!(
166	                            "error: unexpected argument '{}' found\n\n  tip: a similar argument exists: '--{}'\n\n{}\nFor more information, try '--help'.\n",
167	                            a,
168	                            s,
169	                            used_usage(&seen, Some(sname))
170	                        ));
171	                    }
172	                    return Outcome::Fail(format!(
173	                        "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
174	                        a,
175	                        a,
176	                        a,
177	                        generic_usage(&bin)
178	                    ));
179	                }
180	            };
181	            if let Some(o) = handle_opt(def, inline_val, args, &mut i, &mut opts, &mut seen, &mut want_help, &mut want_version, &bin) {
182	                return o;
183	            }
184	            continue;
185	        }
186	        if !only_pos && a.starts_with('-') && a.len() > 1 {
187	            let chars: Vec<char> = a[1..].chars().collect();
188	            let mut k = 0;
189	            while k < chars.len() {
190	                let c = chars[k];
191	                k += 1;
192	                let def = match MAIN_OPTS.iter().find(|d| d.short == Some(c)) {
193	                    Some(d) => d,
194	                    None => {
195	                        let shown = format!("-{}", c);
196	                        return Outcome::Fail(format!(
197	                            "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
198	                            shown,
199	                            shown,
200	                            shown,
201	                            generic_usage(&bin)
202	                        ));
203	                    }
204	                };
205	                if def.value.is_some() {
206	                    let rest: String = chars[k..].iter().collect();
207	                    let iv = if rest.is_empty() { None } else { Some(rest) };
208	                    if let Some(o) = handle_opt(def, iv, args, &mut i, &mut opts, &mut seen, &mut want_help, &mut want_version, &bin) {
209	                        return o;
210	                    }
211	                    break;
212	                }
213	                if let Some(o) = handle_opt(def, None, args, &mut i, &mut opts, &mut seen, &mut want_help, &mut want_version, &bin) {
214	                    return o;
215	                }
216	                if want_help || want_version {
217	                    break;
218	                }
219	            }
220	            if want_help {
221	                return Outcome::Print(sub_help(&bin, HELP_MAIN));
222	            }
223	            if want_version {
224	                return Outcome::Print("lini 1.1.0\n".into());
225	            }
226	            continue;
227	        }
228	        // positional
229	        if input.is_none() && !only_pos && seen.is_empty() && SUBCOMMANDS.contains(&a.as_str()) {
230	            return parse_sub(&bin, &a, &args[i..]);
231	        }
232	        if input.is_none() {
233	            input = Some(a);
234	        } else {
235	            return fail_with_usage(&format!("the subcommand '{}' cannot be used with '<INPUT>'", a), &generic_usage(&bin));
236	        }
237	        if want_help || want_version {
238	            break;
239	        }
240	    }
241	    if want_help {
242	        return Outcome::Print(sub_help(&bin, HELP_MAIN));
243	    }
244	    if want_version {
245	        return Outcome::Print("lini 1.1.0\n".into());
246	    }
247	    if opts.no_warn && opts.strict {
248	        let first = if seen.iter().position(|s| *s == "no-warn") < seen.iter().position(|s| *s == "strict") { ("no-warn", "strict") } else { ("strict", "no-warn") };
249	        return Outcome::Fail(format!(
250	            "error: the argument '--{}' cannot be used with '--{}'\n\nUsage: {} --{} <INPUT>\n\nFor more information, try '--help'.\n",
251	            first.0, first.1, bin, first.0
252	        ));
253	    }
254	    let input = match input {
255	        Some(x) => x,
256	        None => {
257	            return Outcome::Fail(format!(
258	                "error: the following required arguments were not provided:\n  <INPUT>\n\n{}\nFor more information, try '--help'.\n",
259	                used_usage(&seen, None)
260	            ));
261	        }
262	    };
263	    if seen.contains(&"watch") && opts.output.is_none() {
264	        let mut s2 = seen.clone();
265	        s2.push("output");
266	        return Outcome::Fail(format!(
267	            "error: the following required arguments were not provided:\n  --output <OUTPUT>\n\n{}\nFor more information, try '--help'.\n",
268	            used_usage(&s2, None)
269	        ));
270	    }
271	    Outcome::Run(Parsed { cmd: Cmd::Compile { input }, opts })
272	}
