274	#[allow(clippy::too_many_arguments)]
275	fn handle_opt(
276	    def: &OptDef,
277	    inline_val: Option<String>,
278	    args: &[String],
279	    i: &mut usize,
280	    opts: &mut crate::Options,
281	    seen: &mut Vec<&'static str>,
282	    want_help: &mut bool,
283	    want_version: &mut bool,
284	    bin: &str,
285	) -> Option<Outcome> {
286	    if def.long == "help" {
287	        *want_help = true;
288	        return Some(Outcome::Print(sub_help(bin, HELP_MAIN)));
289	    }
290	    if def.long == "version" {
291	        *want_version = true;
292	        return Some(Outcome::Print("lini 1.1.0\n".into()));
293	    }
294	    if seen.contains(&def.long) {
295	        let shown = match def.value {
296	            Some(v) => format!("--{} <{}>", def.long, v),
297	            None => format!("--{}", def.long),
298	        };
299	        return Some(fail_with_usage(&format!("the argument '{}' cannot be used multiple times", shown), &generic_usage(bin)));
300	    }
301	    seen.push(def.long);
302	    let val = if def.value.is_some() {
303	        match inline_val {
304	            Some(v) => Some(v),
305	            None => {
306	                if *i < args.len() {
307	                    let v = args[*i].clone();
308	                    *i += 1;
309	                    Some(v)
310	                } else {
311	                    return Some(Outcome::Fail(format!(
312	                        "error: a value is required for '--{} <{}>' but none was supplied\n\nFor more information, try '--help'.\n",
313	                        def.long,
314	                        def.value.unwrap()
315	                    )));
316	                }
317	            }
318	        }
319	    } else {
320	        None
321	    };
322	    match def.long {
323	        "output" => opts.output = val,
324	        "format" => opts.format = val.unwrap_or_default(),
325	        "theme" => opts.theme = val,
326	        "static" => opts.static_ = true,
327	        "embed-font" => opts.embed_font = true,
328	        "check" => opts.check = true,
329	        "json" => opts.json = true,
330	        "watch" => opts.watch = true,
331	        "no-fs" => opts.no_fs = true,
332	        "no-warn" => opts.no_warn = true,
333	        "strict" => opts.strict = true,
334	        _ => {}
335	    }
336	    None
337	}
