339	fn sub_usage_err(bin: &str, sub: &str, used: &[&str], required: &str) -> Outcome {
340	    let mut parts = vec![bin.to_string(), sub.to_string()];
341	    for u in used {
342	        parts.push(u.to_string());
343	    }
344	    parts.push(required.to_string());
345	    Outcome::Fail(format!(
346	        "error: the following required arguments were not provided:\n  {}\n\nUsage: {}\n\nFor more information, try '--help'.\n",
347	        required,
348	        parts.join(" ")
349	    ))
350	}
