352	fn unexpected(bin: &str, arg: &str, usage: &str) -> Outcome {
353	    let _ = bin;
354	    if arg.starts_with('-') && arg.len() > 1 {
355	        Outcome::Fail(format!(
356	            "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
357	            arg, arg, arg, usage
358	        ))
359	    } else {
360	        Outcome::Fail(format!("error: unexpected argument '{}' found\n\n{}\nFor more information, try '--help'.\n", arg, usage))
361	    }
362	}
