364	fn parse_sub(bin: &str, sub: &str, rest: &[String]) -> Outcome {
365	    let opts = crate::Options { format: "svg".into(), ..Default::default() };
366	    match sub {
367	        "fmt" => {
368	            let usage = format!("Usage: {} fmt [OPTIONS] <INPUT>\n", bin);
369	            let mut check = false;
370	            let mut stdout = false;
371	            let mut used: Vec<&str> = Vec::new();
372	            let mut input = None;
373	            let mut only_pos = false;
374	            for a in rest {
375	                if !only_pos && a == "--" {
376	                    only_pos = true;
377	                    continue;
378	                }
379	                if !only_pos && (a == "-h" || a == "--help") {
380	                    return Outcome::Print(sub_help(bin, HELP_FMT));
381	                }
382	                if !only_pos && a == "--check" {
383	                    check = true;
384	                    used.push("--check");
385	                    continue;
386	                }
387	                if !only_pos && a == "--stdout" {
388	                    stdout = true;
389	                    used.push("--stdout");
390	                    continue;
391	                }
392	                if !only_pos && a.starts_with('-') && a != "-" {
393	                    return unexpected(bin, a, &usage);
394	                }
395	                if input.is_none() {
396	                    input = Some(a.clone());
397	                } else {
398	                    return unexpected(bin, a, &usage);
399	                }
400	            }
401	            match input {
402	                Some(input) => Outcome::Run(Parsed { cmd: Cmd::Fmt { input, check, stdout }, opts }),
403	                None => sub_usage_err(bin, "fmt", &used, "<INPUT>"),
404	            }
405	        }
406	        "desugar" => {
407	            let usage = format!("Usage: {} desugar <INPUT>\n", bin);
408	            let mut input = None;
409	            // `--` ends the options: what follows is positional
410	            let mut only_pos = false;
411	            for a in rest {
412	                if !only_pos && a == "--" {
413	                    only_pos = true;
414	                    continue;
415	                }
416	                if !only_pos && (a == "-h" || a == "--help") {
417	                    return Outcome::Print(sub_help(bin, HELP_DESUGAR));
418	                }
419	                if !only_pos && a.starts_with('-') && a != "-" {
420	                    return unexpected(bin, a, &usage);
421	                }
422	                if input.is_none() {
423	                    input = Some(a.clone());
424	                } else if only_pos {
425	                    return Outcome::Fail(format!(
426	                        "error: unexpected argument '{}' found\n\n{}\nFor more information, try '--help'.\n",
427	                        a, usage
428	                    ));
429	                } else {
430	                    return unexpected(bin, a, &usage);
431	                }
432	            }
433	            match input {
434	                Some(input) => Outcome::Run(Parsed { cmd: Cmd::Desugar { input }, opts }),
435	                None => sub_usage_err(bin, "desugar", &[], "<INPUT>"),
436	            }
437	        }
438	        "highlight" => {
439	            let usage = format!("Usage: {} highlight [OPTIONS] [INPUT]\n", bin);
440	            let mut input = None;
441	            let mut css = false;
442	            for a in rest {
443	                if a == "-h" || a == "--help" {
444	                    return Outcome::Print(sub_help(bin, HELP_HIGHLIGHT));
445	                }
446	                if a == "--css" {
447	                    css = true;
448	                    continue;
449	                }
450	                if a.starts_with('-') && a != "-" {
451	                    return unexpected(bin, a, &usage);
452	                }
453	                if input.is_none() {
454	                    input = Some(a.clone());
455	                } else {
456	                    return unexpected(bin, a, &usage);
457	                }
458	            }
459	            if !css && input.is_none() {
460	                return Outcome::Fail("error: an input file is required — or '--css' for the palette\n".into());
461	            }
462	            Outcome::Run(Parsed { cmd: Cmd::Highlight { input, css }, opts })
463	        }
464	        "theme" => {
465	            let usage = format!("Usage: {} theme [NAME]\n", bin);
466	            let mut name = None;
467	            for a in rest {
468	                if a == "-h" || a == "--help" {
469	                    return Outcome::Print(sub_help(bin, HELP_THEME));
470	                }
471	                if a.starts_with('-') && a != "-" {
472	                    return unexpected(bin, a, &usage);
473	                }
474	                if name.is_none() {
475	                    name = Some(a.clone());
476	                } else {
477	                    return unexpected(bin, a, &usage);
478	                }
479	            }
480	            Outcome::Run(Parsed { cmd: Cmd::Theme { name }, opts })
481	        }
482	        "serve" => {
483	            for a in rest {
484	                if a == "-h" || a == "--help" {
485	                    return Outcome::Print(sub_help(bin, HELP_SERVE));
486	                }
487	            }
488	            Outcome::Run(Parsed { cmd: Cmd::Serve, opts })
489	        }
490	        "help" => {
491	            if rest.is_empty() {
492	                return Outcome::Print(sub_help(bin, HELP_MAIN));
493	            }
494	            let first = rest[0].as_str();
495	            let text = match first {
496	                "fmt" => HELP_FMT,
497	                "serve" => HELP_SERVE,
498	                "desugar" => HELP_DESUGAR,
499	                "highlight" => HELP_HIGHLIGHT,
500	                "theme" => HELP_THEME,
501	                "help" => HELP_HELP,
502	                _ => {
503	                    return fail_with_usage(&format!("unrecognized subcommand '{}'", first), &generic_usage(bin));
504	                }
505	            };
506	            if rest.len() > 1 {
507	                let u = match first {
508	                    "fmt" => format!("Usage: {} fmt [OPTIONS] <INPUT>\n", bin),
509	                    "desugar" => format!("Usage: {} desugar <INPUT>\n", bin),
510	                    "highlight" => format!("Usage: {} highlight [OPTIONS] [INPUT]\n", bin),
511	                    "theme" => format!("Usage: {} theme [NAME]\n", bin),
512	                    "serve" => format!("Usage: {} serve [OPTIONS] [PATH]\n", bin),
513	                    _ => format!("Usage: {} help [COMMAND]...\n", bin),
514	                };
515	                return fail_with_usage(&format!("unrecognized subcommand '{}'", rest[1]), &u);
516	            }
517	            Outcome::Print(sub_help(bin, text))
518	        }
519	        _ => Outcome::Fail(String::new()),
520	    }
521	}

