    17	pub fn css_of(name: &str) -> Option<&'static str> {
    18	    match name {
    19	        "default" => Some(DEFAULT_CSS),
    20	        "light" => Some(LIGHT_CSS),
    21	        "dark" => Some(DARK_CSS),
    22	        "high-contrast" => Some(HC_CSS),
