    27	
    28	// Split "light-dark(a, b)" at its top-level comma.
    29	pub fn split_light_dark(v: &str) -> Option<(String, String)> {
    30	    let inner = v.strip_prefix("light-dark(")?.strip_suffix(')')?;
    31	    let mut depth = 0;
    32	    for (i, c) in inner.char_indices() {
    33	        match c {
    34	            '(' => depth += 1,
    35	            ')' => depth -= 1,
    36	            ',' if depth == 0 => {
    37	                return Some((inner[..i].trim().to_string(), inner[i + 1..].trim().to_string()));
    38	            }
    39	            _ => {}
    40	        }
    41	    }
    42	    None
    43	}
    44	
    45	#[derive(Clone, Debug)]
    46	pub struct Theme {
    47	    pub pair: bool,
    48	    // var name (without --lini-) → (light, dark)
    49	    pub vars: HashMap<String, (String, String)>,
    50	}
    51	
    52	pub fn parse_theme_css(css: &str) -> HashMap<String, (String, String)> {
    53	    let mut m = HashMap::new();
    54	    for line in css.lines() {
    55	        let l = line.trim();
    56	        if let Some(rest) = l.strip_prefix("--lini-") {
    57	            if let Some(colon) = rest.find(':') {
    58	                let name = rest[..colon].to_string();
    59	                let val = rest[colon + 1..].trim().trim_end_matches(';').trim().to_string();
    60	                let pair = split_light_dark(&val).unwrap_or((val.clone(), val.clone()));
    61	                m.insert(name, pair);
    62	            }
    63	        }
    64	    }
    65	    m.insert("font-family".to_string(), (FONT_FAMILY.to_string(), FONT_FAMILY.to_string()));
    66	    m
    67	}
