    69	pub fn builtin(name: &str) -> Option<Theme> {
    70	    let css = css_of(name)?;
    71	    let pair = name == "default" || name == "high-contrast";
    72	    Some(Theme { pair, vars: parse_theme_css(css) })
    73	}
