    75	pub fn resolve(spec: &str) -> Option<Theme> {
    76	    if let Some((a, b)) = spec.split_once('/') {
    77	        let ta = builtin(a)?;
    78	        let tb = builtin(b)?;
    79	        let mut vars = HashMap::new();
    80	        for (k, (l, _)) in &ta.vars {
