    38	
    39	impl Env {
    40	    pub fn eval_term(&self, t: &Term, locals: &HashMap<String, EV>) -> Result<EV, Diag> {
    41	        match t {
    42	            Term::Num(v, _, _) => Ok(EV::Num(*v)),
    43	            Term::Group(e, _) => self.eval(e, locals),
    44	            Term::Call(name, args, sp) => self.call(name, args, locals, *sp),
    45	            Term::Ident(n, sp) => self.lookup(n, locals, *sp),
    46	            Term::Str(s, _) => Ok(EV::Str(s.clone())),
    47	            _ => Err(err("expected a number", t.span())),
    48	        }
    49	    }
    50	
    51	    fn lookup(&self, n: &str, locals: &HashMap<String, EV>, sp: Span) -> Result<EV, Diag> {
    52	        if let Some(v) = locals.get(n) {
    53	            return Ok(v.clone());
    54	        }
    55	        if let Some(v) = self.vars.get(n) {
    56	            return Ok(v.clone());
    57	        }
    58	        match n {
    59	            "pi" => Ok(EV::Num(std::f64::consts::PI)),
    60	            "e" => Ok(EV::Num(std::f64::consts::E)),
    61	            _ => Err(err(&format!("unknown name '{}' in an expression", n), sp)),
    62	        }
    63	    }
    64	
    65	    pub fn eval(&self, e: &Expr, locals: &HashMap<String, EV>) -> Result<EV, Diag> {
    66	        match e {
    67	            Expr::Num(v, _) => Ok(EV::Num(*v)),
    68	            Expr::Percent(v, _) => Ok(EV::Num(*v / 100.0)),
    69	            Expr::Str(s, _) => Ok(EV::Str(s.clone())),
    70	            Expr::Ident(n, sp) => self.lookup(n, locals, *sp),
    71	            Expr::Var(_, sp) | Expr::Hash(_, sp) => Err(err("expected a number", *sp)),
    72	            Expr::Call(name, args, sp) => self.call(name, args, locals, *sp),
    73	            Expr::Unary(op, a, sp) => {
    74	                let v = self.eval(a, locals)?;
    75	                let x = v.num().ok_or_else(|| err("expected a number", *sp))?;
    76	                Ok(EV::Num(match op.as_str() {
    77	                    "-" => -x,
    78	                    "!" => {
    79	                        if x == 0.0 {
    80	                            1.0
    81	                        } else {
    82	                            0.0
    83	                        }
    84	                    }
