    87	            }
    88	            Expr::Bin(op, a, b, sp) => {
    89	                let x = self.eval(a, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
    90	                if op == "&&" {
    91	                    if x == 0.0 {
    92	                        return Ok(EV::Num(0.0));
    93	                    }
    94	                    let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
    95	                    return Ok(EV::Num(if y != 0.0 { 1.0 } else { 0.0 }));
    96	                }
    97	                if op == "||" {
    98	                    if x != 0.0 {
    99	                        return Ok(EV::Num(1.0));
   100	                    }
   101	                    let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
   102	                    return Ok(EV::Num(if y != 0.0 { 1.0 } else { 0.0 }));
   103	                }
   104	                let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
   105	                let b2 = |c: bool| if c { 1.0 } else { 0.0 };
   106	                Ok(EV::Num(match op.as_str() {
   107	                    "+" => x + y,
   108	                    "-" => x - y,
   109	                    "*" => x * y,
   110	                    "/" => x / y,
   111	                    "^" => x.powf(y),
   112	                    "<" => b2(x < y),
   113	                    ">" => b2(x > y),
   114	                    "<=" => b2(x <= y),
   115	                    ">=" => b2(x >= y),
   116	                    "==" => b2(x == y),
   117	                    "!=" => b2(x != y),
   118	                    _ => return Err(err("unknown operator", *sp)),
   119	                }))
   120	            }
   121	            Expr::Ternary(c, a, b, sp) => {
   122	                let cv = self.eval(c, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
   123	                if cv != 0.0 {
   124	                    self.eval(a, locals)
   125	                } else {
   126	                    self.eval(b, locals)
   127	                }
   128	            }
   129	            Expr::Tuple(items, _) => {
   130	                let mut out = Vec::new();
   131	                for it in items {
   132	                    out.push(self.eval(it, locals)?);
   133	                }
   134	                Ok(EV::Tuple(out))
   135	            }
   136	            Expr::Block(binds, body, _) => {
   137	                let mut l2 = locals.clone();
   138	                for (n, ex) in binds {
   139	                    let v = self.eval(ex, &l2)?;
   140	                    l2.insert(n.clone(), v);
   141	                }
   142	                self.eval(body, &l2)
   143	            }
   144	        }
   145	    }
