   147	    fn call(&self, name: &str, args: &[Expr], locals: &HashMap<String, EV>, sp: Span) -> Result<EV, Diag> {
   148	        if let Some(f) = self.funcs.get(name) {
   149	            let mut l2 = locals.clone();
   150	            for (i, p) in f.params.iter().enumerate() {
   151	                let v = match args.get(i) {
   152	                    Some(a) => self.eval(a, locals)?,
   153	                    None => EV::Num(0.0),
   154	                };
   155	                l2.insert(p.clone(), v);
   156	            }
   157	            return self.eval_term(&f.body, &l2);
   158	        }
   159	        let mut xs = Vec::new();
   160	        for a in args {
   161	            match self.eval(a, locals)? {
   162	                EV::Num(v) => xs.push(v),
   163	                _ => return Err(err("expected a number", a.span())),
   164	            }
   165	        }
   166	        let a = |i: usize| xs.get(i).copied().unwrap_or(0.0);
   167	        let v = match name {
   168	            "sin" => a(0).sin(),
   169	            "cos" => a(0).cos(),
   170	            "tan" => a(0).tan(),
   171	            "sqrt" => a(0).sqrt(),
   172	            "abs" => a(0).abs(),
   173	            "exp" => a(0).exp(),
   174	            "ln" => a(0).ln(),
   175	            "log" => a(0).log10(),
   176	            "floor" => a(0).floor(),
   177	            "round" => a(0).round(),
   178	            "pow" => a(0).powf(a(1)),
   179	            "min" => xs.iter().cloned().fold(f64::INFINITY, f64::min),
   180	            "max" => xs.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
   181	            "clamp" => a(0).max(a(1)).min(a(2)),
   182	            _ => return Err(err(&format!("unknown function '{}'", name), sp)),
   183	        };
   184	        Ok(EV::Num(v))
   185	    }
   186	}

 110	    };
 111	    for d in type_defaults(t) {
 112	        set(&d.name, &d.value);
 113	    }
 114	    if let Some(df) = ctx.sheet.define(t) {
 115	        for d in &df.decls {
