 849	fn shadow_filter(ctx: &Ctx, i: usize, out: &mut Out) -> Option<String> {
 850	    let xs = prop_nums(ctx, i, "shadow");
 851	    if xs.len() < 3 {
 852	        return None;
 853	    }
 854	    let theme = crate::theme::resolve("default").unwrap();
 855	    let col = theme.light_value("shadow-color").unwrap_or_default();
 856	    let key = format!("{},{},{},{}", f4(xs[0]), f4(xs[1]), f4(xs[2]), col);
 857	    let id = format!("lini-shadow-{}", hash8(&key));
 858	    let def = format!(
 859	        "<filter id=\"{}\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\"><feDropShadow dx=\"{}\" dy=\"{}\" stdDeviation=\"{}\" flood-color=\"{}\"/></filter>",
 860	        id,
 861	        f4(xs[0]),
 862	        f4(xs[1]),
 863	        f4(xs[2]),
 864	        col
 865	    );
 866	    if !out.defs.contains(&def) {
 867	        out.defs.push(def);
 868	    }
 869	    Some(id)
 870	}
