 872	pub fn render_node(ctx: &Ctx, i: usize, ind_n: usize, s: &mut String, out: &mut Out) -> Result<(), Diag> {
 873	    let n = &ctx.nodes[i];
 874	    let c = &ctx.comp[i];
 875	    if n.prim == Prim::Text {
 876	        return render_text(ctx, i, ind_n, s, out);
 877	    }
 878	    if crate::drawing::is_chrome(ctx, i) {
 879	        return crate::drawing::render_chrome(ctx, i, ind_n, s, out);
 880	    }
 881	    let href = prop_str(ctx, i, "href");
 882	    let mut ind_n = ind_n;
 883	    if let Some(h) = &href {
 884	        s.push_str(&format!("{}<a href=\"{}\">\n", ind(ind_n), xml_escape(h)));
 885	        ind_n += 2;
 886	    }
 887	    let cls = node_classes(ctx, i, out);
 888	    if n.is("table") {
 889	        // a table resolves its header band's look whether or not a band is drawn
 890	        let hp = type_rule_props(ctx, "header");
 891	        let _ = css_decls(ctx, &hp, &mut out.vars, 2.0, false)?;
 892	    }
 893	    let style = inline_style(ctx, i, out, false)?;
 894	    let mut head = format!("{}<g class=\"{}\"", ind(ind_n), cls);
 895	    if let Some(id) = &n.id {
 896	        head.push_str(&format!(" data-id=\"{}\"", xml_escape(id)));
 897	    }
 898	    if !style.is_empty() {
 899	        head.push_str(&format!(" style=\"{}\"", xml_escape(&style)));
 900	    }
 901	    let tx = n.x + c.translate.0 + n.geo_off.0;
 902	    let ty = n.y + c.translate.1 + n.geo_off.1;
 903	    head.push_str(&format!(" transform=\"translate({},{})", f4(tx), f4(ty)));
 904	    if c.rotate != 0.0 {
 905	        head.push_str(&format!(" rotate({})", f4(c.rotate)));
 906	    }
 907	    head.push_str("\">\n");
 908	    s.push_str(&head);
 909	    let ci = ind_n + 2;
 910	    if let Some(hint) = prop_str(ctx, i, "hint") {
 911	        s.push_str(&format!("{}<title>{}</title>\n", ind(ci), xml_escape(&hint)));
 912	    }
 913	    if crate::chart::is_chart(ctx, i) {
 914	        crate::chart::render(ctx, i, ci, s, out)?;
 915	        s.push_str(&format!("{}</g>\n", ind(ind_n)));
 916	        if href.is_some() {
 917	            s.push_str(&format!("{}</a>\n", ind(ind_n - 2)));
 918	        }
 919	        return Ok(());
 920	    }
 921	    // a closed outline with no area is not drawn
 922	    let empty = matches!(n.prim, Prim::Block | Prim::Oval | Prim::Hex | Prim::Slant | Prim::Cyl | Prim::Diamond) && (n.w <= 0.0 || n.h <= 0.0);
 923	    let shape = if empty { vec![] } else { shape_lines(ctx, i) };
 924	    if shape.iter().any(|l| l.contains("lini-marker")) {
 925	        out.markers = true;
 926	    }
 927	    let multiple = prop_nums(ctx, i, "multiple").first().copied();
 928	    let shadow = shadow_filter(ctx, i, out);
 929	    let mut si = ci;
 930	    if let Some(id) = &shadow {
 931	        s.push_str(&format!("{}<g filter=\"url(#{})\">\n", ind(si), id));
 932	        si += 2;
 933	    }
 934	    if let Some(m) = multiple {
 935	        s.push_str(&format!("{}<g transform=\"translate({},{})\">\n", ind(si), f4(m), f4(-m)));
 936	        for l in &shape {
 937	            s.push_str(&format!("{}{}\n", ind(si + 2), l));
 938	        }
 939	        s.push_str(&format!("{}</g>\n", ind(si)));
 940	    }
 941	    for l in &shape {
 942	        s.push_str(&format!("{}{}\n", ind(si), l));
 943	    }
 944	    if shadow.is_some() {
 945	        s.push_str(&format!("{}</g>\n", ind(ci)));
 946	    }
 947	    if !n.gutters.is_empty() {
 948	        let fill = match ctx.nodes[i].props.get("gap-fill").and_then(single_term) {
 949	            Some(t) => color_css(t, &mut out.vars, t.span())?,
 950	            None => String::new(),
 951	        };
 952	        out.gutters = true;
 953	        for &(x, y, w, h) in &n.gutters {
 954	            s.push_str(&format!(
 955	                "{}<rect class=\"lini-gutter\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" fill=\"{}\"/>\n",
 956	                ind(ci),
 957	                f4(x),
 958	                f4(y),
 959	                f4(w),
 960	                f4(h),
 961	                xml_escape(&fill)
 962	            ));
 963	        }
 964	    }
 965	    let ordered = paint_order(ctx, &n.children);
 966	    for ch in ordered {
 967	        render_node(ctx, ch, ci, s, out)?;
 968	    }
 969	    s.push_str(&format!("{}</g>\n", ind(ind_n)));
 970	    if href.is_some() {
 971	        s.push_str(&format!("{}</a>\n", ind(ind_n - 2)));
 972	    }
 973	    Ok(())
 974	}
