 997	pub fn slot_rank(slot: &str) -> (usize, String) {
 998	    if let Some(rest) = slot.strip_prefix("@define:") {
 999	        let p = SLOT_ORDER.iter().position(|s| *s == "@define").unwrap();
1000	        return (p, rest.to_string());
1001	    }
1002	    if let Some(rest) = slot.strip_prefix("@class:") {
1003	        let p = SLOT_ORDER.iter().position(|s| *s == "@class").unwrap();
1004	        return (p, rest.to_string());
1005	    }
1006	    match SLOT_ORDER.iter().position(|s| *s == slot) {
1007	        Some(p) => (p, String::new()),
1008	        None => (SLOT_ORDER.len(), slot.to_string()),
1009	    }
1010	}
