  26	fn rd16(d: &[u8], o: usize) -> u16 {
  27	    u16::from_be_bytes([d[o], d[o + 1]])
  28	}
  29	fn rd32(d: &[u8], o: usize) -> u32 {
  30	    u32::from_be_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
  31	}
  32	
  33	impl Font {
  34	    fn parse(data: &'static [u8]) -> Font {
  35	        let n = rd16(data, 4) as usize;
  36	        let mut tables: HashMap<String, (usize, usize)> = HashMap::new();
  37	        for i in 0..n {
  38	            let o = 12 + 16 * i;
  39	            let tag = String::from_utf8_lossy(&data[o..o + 4]).to_string();
  40	            tables.insert(tag, (rd32(data, o + 8) as usize, rd32(data, o + 12) as usize));
  41	        }
  42	        let head = tables["head"].0;
  43	        let upem = rd16(data, head + 18) as f64;
  44	        let index_to_loc = rd16(data, head + 50) as i16;
  45	        let hhea = tables["hhea"].0;
  46	        let ascent = rd16(data, hhea + 4) as i16;
  47	        let descent = rd16(data, hhea + 6) as i16;
  48	        let nhm = rd16(data, hhea + 34) as usize;
  49	        let maxp = tables["maxp"].0;
  50	        let ng = rd16(data, maxp + 4) as usize;
  51	        let hmtx = tables["hmtx"].0;
  52	        let mut adv = Vec::with_capacity(ng);
  53	        for i in 0..ng {
  54	            if i < nhm {
  55	                adv.push(rd16(data, hmtx + 4 * i));
  56	            } else {
  57	                let last = *adv.last().unwrap_or(&0);
  58	                adv.push(last);
  59	            }
  60	        }
  61	        let mut cmap = HashMap::new();
  62	        let cm = tables["cmap"].0;
  63	        let nt = rd16(data, cm + 2) as usize;
  64	        for i in 0..nt {
  65	            let so = cm + rd32(data, cm + 4 + 8 * i + 4) as usize;
  66	            let fmt = rd16(data, so);
  67	            if fmt == 12 {
  68	                let ngr = rd32(data, so + 12) as usize;
  69	                for j in 0..ngr {
