   2	//
   3	// The artwork table (data/icons.txt) holds every symbol on a 256×256 canvas in
   4	// three layers: the duotone body (painted with the node's fill), the line work
   5	// (stroked with the node's stroke, counter-scaled so the stroke width stays
   6	// even at any size) and dots (filled with the stroke colour). Each entry also
   7	// carries its artwork bounding box, which `fit: contain | cover | stretch`
   8	// frame to the node; `fit: auto` maps the whole 256 canvas.
   9	//
  10	// An icon is a square: its side is the larger of its laid-out width and height
  11	// (children flow inside it like a block's, gap 0 by default).
  12	
  13	use crate::ast::{Decl, Term};
  14	use crate::compile::{get, Ctx};
