  22	pub struct IconDef {
  23	    pub name: &'static str,
  24	    // translate that centres the artwork bbox, as printed (`-128`, `-128.028`)
  25	    pub tx: &'static str,
  26	    pub ty: &'static str,
  27	    // artwork bbox size
  28	    pub bw: f64,
  29	    pub bh: f64,
  30	    pub body: Vec<&'static str>,
  31	    pub line: Vec<&'static str>,
  32	    pub dots: Vec<&'static str>,
  33	}
  34	
  35	static DATA: &str = include_str!("../data/icons.txt");
  36	static TABLE: OnceLock<Vec<IconDef>> = OnceLock::new();
  37	
  38	// Every icon, sorted by name.
  39	pub fn table() -> &'static [IconDef] {
  40	    TABLE.get_or_init(|| {
  41	        let mut out: Vec<IconDef> = Vec::new();
  42	        for line in DATA.lines() {
  43	            if line.starts_with('#') || line.is_empty() {
  44	                continue;
  45	            }
  46	            if let Some(head) = line.strip_prefix('@') {
  47	                let f: Vec<&'static str> = head.split(' ').collect();
  48	                out.push(IconDef {
  49	                    name: f[0],
  50	                    tx: f[1],
  51	                    ty: f[2],
  52	                    bw: f[3].parse().unwrap_or(256.0),
  53	                    bh: f[4].parse().unwrap_or(256.0),
  54	                    body: vec![],
  55	                    line: vec![],
  56	                    dots: vec![],
  57	                });
  58	                continue;
  59	            }
  60	            let d = match out.last_mut() {
  61	                Some(d) => d,
  62	                None => continue,
  63	            };
  64	            let (kind, el) = line.split_at(2);
  65	            match kind {
  66	                "b " => d.body.push(el),
  67	                "l " => d.line.push(el),
  68	                "d " => d.dots.push(el),
  69	                _ => {}
  70	            }
  71	        }
  72	        out.sort_by(|a, b| a.name.cmp(b.name));
  73	        out
  74	    })
  75	}
  76	
  77	pub fn find(name: &str) -> Option<&'static IconDef> {
  78	    let t = table();
  79	    t.binary_search_by(|d| d.name.cmp(name)).ok().map(|k| &t[k])
  80	}
  81	
  82	// Up to three names within two edits, nearest first, then by name.
  83	pub fn suggestions(name: &str) -> Vec<&'static str> {
  84	    let mut c: Vec<(usize, &'static str)> = table()
  85	        .iter()
  86	        .filter_map(|d| {
  87	            let k = levenshtein(name, d.name);
  88	            if k <= 2 {
  89	                Some((k, d.name))
  90	            } else {
  91	                None
  92	            }
  93	        })
  94	        .collect();
  95	    c.sort();
  96	    c.into_iter().take(3).map(|(_, n)| n).collect()
  97	}
  98	
  99	pub fn unknown_icon(name: &str) -> String {
 100	    let s = suggestions(name);
 101	    if s.is_empty() {
 102	        format!("unknown icon '{}'", name)
 103	    } else {
 104	        let q: Vec<String> = s.iter().map(|n| format!("'{}'", n)).collect();
 105	        format!("unknown icon '{}'; did you mean {}?", name, q.join(", "))
 106	    }
 107	}
