 83	// the root's config: layout, unit, density, and the scene as a tree
 84	fn setup(cx: &mut lower::Cx, doc: &syntax::Doc) -> Result<(), Diag> {
 85	    if let Some(l) = sheet::root_layout(&doc.sheet) {
 86	        cx.root_layout = l;
 87	    }
 88	    for (it, _) in &doc.sheet {
 89	        if let syntax::SItem::Decl(d) = it {
 90	            if d.name == "unit" {
 91	                cx.root_unit = d.first().map(|s| s.to_string());
 92	            }
 93	            if d.name == "thickness" {
 94	                cx.root_thickness = lower::thickness_of(d);
 95	            }
 96	            if d.name == "density" {
 97	                match d.first().and_then(|s| s.parse::<f64>().ok()) {
 98	                    Some(v) if v > 0.0 => cx.density = v,
 99	                    _ => {
100	                        if cx.density_err.is_none() {
101	                            cx.density_err = Some(Diag::error("value", "'density' must be > 0", d.span));
102	                        }
103	                    }
104	                }
105	            }
106	        }
107	    }
108	    // the root's unit is checked before any node's
109	    let unit = doc.sheet.iter().rev().find_map(|(it, _)| match it {
110	        syntax::SItem::Decl(d) if d.name == "unit" => Some(d),
111	        _ => None,
112	    });
113	    if let Some(d) = unit {
114	        if !sheet::unit_ok(d) {
115	            cx.unit_err = Some(lower::err("'unit' is px, mm, cm, m, or in", d.span));
116	        }
117	    }
118	    // a scene of sheets alone sits flush
119	    cx.root_pages = !doc.stmts.is_empty()
120	        && doc.stmts.iter().all(|s| match s {
121	            syntax::Stmt::Node(n) => {
122	                let ty = n.ty.clone().unwrap_or_else(|| "box".to_string());
123	                cx.chain(&ty).map_or(false, |(_, c)| c.iter().any(|t| t == "page"))
124	            }
125	            _ => false,
126	        });
127	    if cx.root_layout == "sequence" {
128	        cx.mark("line");
129	        cx.mark("block");
130	    }
131	    // the scene as a tree: `layout: tree`, or mindmaps at the top
132	    if cx.root_layout == "tree" {
133	        let d = doc.sheet.iter().rev().find_map(|(it, _)| match it {
134	            syntax::SItem::Decl(d) if d.name == "direction" => d.first().map(|s| s.to_string()),
135	            _ => None,
136	        });
137	        // mindmaps in the tree bring their direction and routing
138	        let mindmaps = tree::has_mindmap(cx, &doc.stmts);
139	        tree::check_roots(cx, &doc.stmts, crate::diag::Span::new(0, 0))?;
140	        let hoisted = mindmaps && d.is_none();
141	        let dir = if hoisted {
142	            match tree::mindmap_dir(cx, &doc.stmts) {
143	                Some((d, sp)) => tree::read_dir(cx, Some(d), sp)?,
144	                None => "bilateral".to_string(),
145	            }
146	        } else {
147	            tree::read_dir(cx, d, crate::diag::Span::new(0, 0))?
148	        };
149	        if mindmaps {
150	            cx.root_mindmap = true;
151	            cx.root_mindmap_dir = dir.clone();
152	        }
153	        let sem = if hoisted { "column".to_string() } else { dir.clone() };
154	        cx.root_tree = Some(tree::TreeMode { mindmap: false, dir, level: 0, side: None, hue: None, hoisted, sem });
155	    } else if !doc.sheet.iter().any(|(it, _)| matches!(it, syntax::SItem::Decl(d) if d.name == "layout"))
156	        && doc.stmts.iter().any(|s| matches!(s, syntax::Stmt::Node(n) if tree::is_mindmap(cx, n)))
157	    {
158	        cx.root_layout = "tree".to_string();
159	        cx.root_mindmap = true;
160	        let own_dir = doc.sheet.iter().rev().find_map(|(it, _)| match it {
161	            syntax::SItem::Decl(d) if d.name == "direction" => d.first().map(|s| s.to_string()),
162	            _ => None,
163	        });
164	        let hoisted = own_dir.is_none();
165	        let dir = match own_dir {
166	            // the scene's own direction lays out, unchecked
167	            Some(d) => d,
168	            None => match tree::mindmap_dir(cx, &doc.stmts) {
169	                Some((d, sp)) => tree::read_dir(cx, Some(d), sp)?,
170	                None => "bilateral".to_string(),
171	            },
172	        };
173	        cx.root_mindmap_dir = dir.clone();
174	        cx.root_tree =
175	            Some(tree::TreeMode { mindmap: true, dir, level: 0, side: None, hue: None, hoisted, sem: "bilateral".to_string() });
176	    }
177	    Ok(())
178	}

