   271	    fn run(&self, source: &str, filename: &str, opts: &lini::Options) -> u8 {
   272	        if self.form == Form::Json {
   273	            let (doc, worst) = lini::diagnostics_json(source, opts, filename);
   274	            print!("{}", doc);
   275	            return self.exit_for(worst);
   276	        }
   277	        let result = match self.form {
   278	            Form::Check => lini::check_with(source, opts).map(|diags| (None, diags)),
   279	            _ => lini::compile_str_checked(source, opts).map(|(svg, diags)| (Some(svg), diags)),
   280	        };
   281	        let (svg, diags) = match result {
   282	            Ok(built) => built,
   283	            Err(e) => {
   284	                eprintln!("{}", e.display_with_source(source, filename));
   285	                return 1;
   286	            }
   287	        };
   288	        if !self.no_warn {
   289	            for d in &diags {
   290	                eprintln!("{}", d.display_with_source(source, filename));
   291	            }
   292	        }
   293	        if let Some(svg) = svg {
   294	            match &self.output {
   295	                Some(path) => {
   296	                    if let Err(e) = std::fs::write(path, svg.as_bytes()) {
   297	                        eprintln!("error: write {}: {}", path.display(), e);
   298	                        return 2;
   299	                    }
   300	                }
   301	                None => print!("{}", svg),
   302	            }
   303	        }
   304	        self.exit_for(lini::Level::worst(&diags))
   305	    }
