   307	    fn exit_for(&self, worst: Option<lini::Level>) -> u8 {
   308	        match worst {
   309	            Some(lini::Level::Error) => 1,
   310	            Some(lini::Level::Warning) if self.strict => 1,
   311	            _ => 0,
   312	        }
   375	    }
