    82	        Term::Group(e, _) => env.eval(e, &HashMap::new()).ok().and_then(|x| x.num()),
    83	        Term::Call(..) => env.eval_term(t, &HashMap::new()).ok().and_then(|x| x.num()),
    84	        Term::Ident(n, _) => match env.vars.get(n) {
