    59	    sheet::check_selectors(&cx, &doc.sheet)?;
    60	    if cx.root_layout == "schematic" {
    61	        cx.sch_ops(&doc.stmts)?;
    62	        let plan = cx.sch_plan(&doc.stmts, true, 0)?;
    63	        cx.root_sch = Some(plan);
    64	    }
    65	    let mut items = Vec::new();
    66	    cx.stmts(&doc.stmts, &mut items)?;
